window.__ModuleLoader__.load({
  id: '@local/conversation-elements',
  factory(require) {
    const { createElement, useLayoutEffect, useRef } = require('react');
    const slot = 'conversation.composer.dock';
    const idleMs = 60_000;

    function svgUrl(body, box) {
      const svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="' + box + '" width="' +
        box.split(' ')[2] + '" height="' + box.split(' ')[3] + '">' + body + '</svg>';
      return 'url("data:image/svg+xml,' + encodeURIComponent(svg) + '")';
    }
    const hammer = svgUrl(`
      <defs>
        <linearGradient id="steel" x2=".32" y2="1" gradientUnits="objectBoundingBox">
          <stop stop-color="#f5fcff"/><stop offset=".38" stop-color="#b1cdd9"/>
          <stop offset=".48" stop-color="#658794"/><stop offset="1" stop-color="#354d60"/>
        </linearGradient>
        <linearGradient id="wood"><stop stop-color="#744126"/><stop offset=".55" stop-color="#da9955"/><stop offset="1" stop-color="#a46132"/></linearGradient>
      </defs>
      <g transform="rotate(-35 17 14)" stroke="#253847" stroke-linejoin="round">
        <path fill="url(#wood)" d="M14 13h6l1 26q-3 4-7 0z"/>
        <path fill="#354759" d="m14 28 7-1 1 12q-4 5-9 1z"/>
        <path stroke="#85949a" d="m15 32 5-2m-5 6 5-2"/>
        <path fill="url(#steel)" d="M3 8h6l2 2 10-2q7-1 12 7l-8-2-5 5h-8l-3-3-5 1z"/>
        <path fill="#d9eef6" d="m2 8 4-1 2 10-5 1z"/>
        <path stroke="#f7feff" fill="none" d="m12 11 10-2 5 1"/>
      </g>`, '0 0 46 46');
    // 每帧火纹沿边缘平铺，首尾相接。
    const flame = 'url("data:image/webp;base64,")';
    const frost = svgUrl('<g fill="#e2f9ff" fill-opacity=".16" stroke="#f5feff" stroke-opacity=".42" stroke-width=".9"><path d="m0 12 55 27 35-39-16 60-19-21 5 44-60-71Zm74 48 46 29-60-6 14-23Zm46 29 49-73-16 62-33 11Zm0 0 40 71-54-40Zm-60-6-35 77 7-49Z"/></g>', '0 0 180 160');
    // 用有透明边缘的薄雾纹理，移动时只改变图层的位置和透明度。
    const mist = 'url("data:image/webp;base64,")';
    const icePaint = 'radial-gradient(ellipse at center,transparent 28%,#96cfe7b8 100%),' +
      frost + ' 0 0 / 240px 210px repeat,linear-gradient(135deg,#edfaff70,#7fbdda66 52%,#e1f7ff99)';
    const css = `
      .ce-fire{position:absolute;bottom:calc(100% - 2px);left:12px;right:12px;height:0;z-index:4;pointer-events:none}
      .ce-plume{position:absolute;bottom:0;height:var(--height);transform-origin:50% 100%}
      .ce-plume::before{content:"";position:absolute;inset:0;background-image:${flame};background-repeat:repeat-x;background-size:var(--texture-width) 4800%;background-position-x:var(--offset);mask-image:linear-gradient(90deg,transparent,#000 19%,#000 77%,transparent);transform-origin:50% 100%}
      .ce-ember{position:absolute;left:54%;bottom:57%;width:3px;height:6px;border-radius:65% 35% 70% 40%;background:radial-gradient(ellipse at 50% 65%,#ffdf83,#ff923d 48%,transparent 75%);opacity:0}
      .ce-ice{position:fixed;inset:0;width:100vw;height:100vh;max-width:none;max-height:none;margin:0;padding:0;border:0;overflow:hidden;background:${icePaint};backdrop-filter:blur(3px) saturate(.65);cursor:${hammer} 3 17,pointer;touch-action:none;color:#183d56}
      .ce-ice::backdrop{background:transparent}
      .ce-mist{position:absolute;inset:0;overflow:hidden;pointer-events:none}
      .ce-mist::before,.ce-mist::after{content:"";position:absolute;width:68%;height:clamp(90px,24vh,240px);background:${mist} center/100% 100% no-repeat;opacity:.58}
      .ce-mist::before{bottom:-4%;left:-12%;--mist-x:5%;--mist-y:-34%;--mist-mirror:1}
      .ce-mist::after{bottom:2%;right:-19%;--mist-x:-8%;--mist-y:-45%;--mist-mirror:-1;transform:scaleX(-1)}
      .ce-ice[data-broken] .ce-mist{opacity:0;transition:opacity 180ms ease-out}
      @keyframes ce-vapor{
        0%{opacity:0;transform:translateY(12%) scaleX(var(--mist-mirror))}
        38%{opacity:.78}
        100%{opacity:0;transform:translate(var(--mist-x),var(--mist-y)) scale(var(--mist-mirror),1.32)}
      }
      @media(prefers-reduced-motion:no-preference){
        .ce-mist::before{animation:ce-vapor 7.4s ease-in-out -2.3s infinite}
        .ce-mist::after{animation:ce-vapor 9.1s ease-in-out -5.7s infinite}
      }
      .ce-ice span{position:absolute;left:50%;bottom:12%;transform:translateX(-50%);border:1px solid #ffffffaa;border-radius:30px;padding:8px 18px;background:#eefbffe3;white-space:nowrap;font:500 14px/1.5 system-ui}
      .ce-ice[data-broken]{background:transparent;backdrop-filter:none}
      .ce-ice[data-broken] span{display:none}
      .ce-ice i{position:absolute;background:${icePaint};animation:ce-shard 620ms var(--delay) both;pointer-events:none}
      .ce-cracks{position:absolute;inset:0;width:100%;height:100%;fill:none;stroke:#eaffff;stroke-width:1.4;filter:drop-shadow(0 1px 1px #326782);animation:ce-crack-fade 240ms 125ms forwards}
      .ce-cracks path{stroke-dasharray:1;animation:ce-split 150ms ease-out both}
      @keyframes ce-split{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}
      @keyframes ce-crack-fade{to{opacity:0}}
      @keyframes ce-shard{
        0%{transform:none;opacity:1;animation-timing-function:ease-out}
        22%{transform:translate(var(--kick),-6px) rotate(var(--tilt));opacity:.97;animation-timing-function:ease-in}
        100%{transform:perspective(650px) translate(var(--dx),var(--fall)) rotateX(var(--flip)) rotate(var(--spin));opacity:0}
      }
      @keyframes ce-burn{to{background-position-y:100%}}
      @keyframes ce-sway{0%,100%{transform:scaleY(.76) skewX(-3deg)}48%{transform:scaleY(1) skewX(4deg)}75%{transform:scaleY(.87) skewX(1deg)}}
      @keyframes ce-lift{0%,48%{opacity:0;transform:none}54%{opacity:.8}72%{opacity:.55;transform:translate(3px,-9px) scale(.76)}96%,100%{opacity:0;transform:translate(var(--drift),-24px) scale(.18)}}
      @media(prefers-reduced-motion:no-preference){
        .ce-plume::before{animation:ce-burn var(--cycle) steps(47,end) var(--phase) infinite}
        .ce-plume{animation:ce-sway var(--sway) ease-in-out var(--phase) infinite}
        .ce-ember{animation:ce-lift var(--lift) ease-out var(--phase) infinite}
      }
      @media(prefers-reduced-motion:reduce){.ce-ice i{animation:none}}
    `;

    function showFire(pane) {
      const rim = document.createElement('div');
      rim.className = 'ce-fire';
      rim.setAttribute('aria-hidden', 'true');
      // 按输入框宽度划分火簇，火苗的高度、宽度和摆动周期分别取样。
      const count = Math.max(4, Math.round(pane.clientWidth / 55) || 4);
      const origin = Math.random() * Math.PI * 2;
      for (let i = 0; i < count; i++) {
        const plume = document.createElement('div');
        plume.className = 'ce-plume';
        const crest = (1 + Math.sin(i * 1.73 + origin)) / 2;
        const height = 9 + 43 * crest ** 1.7 + Math.random() * 8;
        const breadth = .68 + Math.random() * .43;
        plume.style.left = ((i + (1 - breadth) / 2) * 100 / count) + '%';
        plume.style.width = (breadth * 100 / count) + '%';
        plume.style.setProperty('--height', height + 'px');
        plume.style.setProperty('--texture-width', (95 + Math.random() * 95) + 'px');
        plume.style.setProperty('--offset', -Math.random() * 180 + 'px');
        plume.style.setProperty('--cycle', (1.2 + Math.random() * .8) + 's');
        plume.style.setProperty('--sway', (1.7 + Math.random() * 1.5) + 's');
        plume.style.setProperty('--phase', -Math.random() * 5 + 's');
        rim.append(plume);
        if (crest > .65) {
          const ember = document.createElement('i');
          ember.className = 'ce-ember';
          ember.style.setProperty('--lift', (1.4 + Math.random() * 1.6) + 's');
          ember.style.setProperty('--drift', (Math.random() * 21 - 8) + 'px');
          plume.append(ember);
        }
      }
      pane.append(rim);
      return () => rim.remove();
    }

    function fracture(dialog, x, y, width, height) {
      const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
      svg.setAttribute('class', 'ce-cracks');
      svg.setAttribute('aria-hidden', 'true');
      const impact = [x, y];
      const edge = [];
      for (const [ax, ay, bx, by] of [[0,0,width,0],[width,0,width,height],[width,height,0,height],[0,height,0,0]]) {
        for (let i = 0; i < 4; i++) {
          const t = (i + (i ? Math.random() * .5 : 0)) / 4;
          edge.push([ax + (bx - ax) * t, ay + (by - ay) * t]);
        }
      }
      // 共用相邻冰片的顶点，裂纹和碎片边缘始终吻合。
      const rings = [edge.map(() => impact)];
      for (const radius of [.12, .42, 1]) {
        rings.push(edge.map(([ex, ey]) => {
          const t = radius === 1 ? 1 : radius * (.7 + Math.random() * .6);
          return [x + (ex - x) * t, y + (ey - y) * t];
        }));
      }
      function crack(points) {
        const line = document.createElementNS(svg.namespaceURI, 'path');
        line.setAttribute('d', 'M' + points.map(point => point.join(',')).join(' L'));
        line.setAttribute('pathLength', '1');
        svg.append(line);
      }
      for (let i = 0; i < edge.length; i++) {
        const next = (i + 1) % edge.length;
        crack(rings.map(ring => ring[i]));
        for (let r = 1; r < rings.length; r++) {
          const points = [rings[r-1][i], rings[r][i], rings[r][next], rings[r-1][next]];
          if (r < rings.length - 1) crack(points.slice(1, 3));
          const xs = points.map(p => p[0]), ys = points.map(p => p[1]);
          const left = Math.min(...xs), top = Math.min(...ys);
          const shard = document.createElement('i');
          const drift = (xs.reduce((a,b) => a+b, 0) / 4 - x) * .14;
          Object.assign(shard.style, {
            left: left + 'px', top: top + 'px', width: (Math.max(...xs)-left) + 'px',
            height: (Math.max(...ys)-top) + 'px',
            clipPath: 'polygon(' + points.map(([px,py]) => (px-left)+'px '+(py-top)+'px').join(',') + ')',
            backgroundSize: width+'px '+height+'px,240px 210px,'+width+'px '+height+'px',
            backgroundPosition: -left+'px '+(-top)+'px',
          });
          const spin = (Math.random() - .5) * 48;
          shard.style.setProperty('--delay', (70 + r*30 + Math.random()*45)+'ms');
          shard.style.setProperty('--kick', drift*.25+'px');
          shard.style.setProperty('--dx', drift+'px');
          shard.style.setProperty('--tilt', spin*.1+'deg');
          shard.style.setProperty('--spin', spin+'deg');
          shard.style.setProperty('--flip', (Math.random()-.5)*100+'deg');
          shard.style.setProperty('--fall', (height*(.16+Math.random()*.32))+'px');
          dialog.append(shard);
        }
      }
      dialog.append(svg);
    }

    function showIce(thaw) {
      const dialog = document.createElement('dialog');
      dialog.className = 'ce-ice';
      dialog.setAttribute('aria-label', '页面已冻结，点击破冰');
      const hint = document.createElement('span');
      hint.textContent = '点击任意位置破冰';
      const vapor = document.createElement('div');
      vapor.className = 'ce-mist';
      vapor.setAttribute('aria-hidden', 'true');
      dialog.append(vapor);
      dialog.append(hint);
      let timer;
      function breakIce(event) {
        event.preventDefault();
        event.stopPropagation();
        if (dialog.hasAttribute('data-broken')) return;
        dialog.setAttribute('data-broken', '');
        if (matchMedia('(prefers-reduced-motion: reduce)').matches) return thaw();
        const x = event.detail ? event.clientX : innerWidth / 2;
        const y = event.detail ? event.clientY : innerHeight / 2;
        fracture(dialog, x, y, innerWidth, innerHeight);
        timer = setTimeout(thaw, 850);
      }
      dialog.onclick = breakIce;
      dialog.oncancel = breakIce;
      dialog.onkeydown = event => {
        if (event.key === 'Enter' || event.key === ' ') breakIce(event);
      };
      document.body.append(dialog);
      dialog.showModal();
      return () => { clearTimeout(timer); dialog.close(); dialog.remove(); };
    }

    function watchIdle(freeze) {
      let lastActivity = Date.now();
      let release;
      let timer;
      function activity() { if (!release) lastActivity = Date.now(); }
      function check() {
        const remaining = lastActivity + idleMs - Date.now();
        if (remaining > 0) { timer = setTimeout(check, remaining); return; }
        release = freeze(() => {
          release();
          release = undefined;
          activity();
          timer = setTimeout(check, idleMs);
        });
      }
      const events = ['pointermove', 'pointerdown', 'keydown', 'input', 'wheel', 'scroll', 'touchmove'];
      for (const type of events) window.addEventListener(type, activity, { capture: true, passive: true });
      timer = setTimeout(check, idleMs);
      return () => {
        clearTimeout(timer);
        for (const type of events) window.removeEventListener(type, activity, true);
        release?.();
      };
    }

    function Effects({ sessionId, useSession, useSessionRetainInfo }) {
      const marker = useRef(null);
      const running = useSession(state => state.running);
      const main = useSessionRetainInfo(info => (info?.retainedBy.mainView ?? 0) > 0);
      useLayoutEffect(() => {
        const pane = marker.current?.closest('[data-conversation-session]');
        if (!main || !sessionId || pane?.dataset.conversationSession !== sessionId) return;
        let dispose;
        let visible = false;
        let stopped = false;
        const sync = () => {
          dispose?.();
          dispose = undefined;
          if (!visible || document.hidden) return;
          if (running) {
            const card = marker.current?.closest('[data-composer-dock]')?.parentElement?.querySelector('[data-composer-card]');
            if (card) dispose = showFire(card);
          } else dispose = watchIdle(showIce);
        };
        const observer = new IntersectionObserver(([entry]) => {
          if (stopped || entry.isIntersecting === visible) return;
          visible = entry.isIntersecting;
          sync();
        });
        observer.observe(pane);
        document.addEventListener('visibilitychange', sync);
        return () => {
          stopped = true;
          observer.disconnect();
          document.removeEventListener('visibilitychange', sync);
          dispose?.();
        };
      }, [sessionId, main, running]);
      return createElement('span', { ref: marker, hidden: true });
    }
    return {
      inject: ['slots'],
      apply(ctx) {
        ctx.effect(() => {
          const style = document.createElement('style');
          style.textContent = css;
          document.head.append(style);
          return () => style.remove();
        });
        ctx.slots.inject(slot, () => ctx.slots.register({ name: slot, id: 'conversation-elements' }, Effects));
      },
    };
  },
});
